const topicTypes={l0:'concept',l1:'queue',l2:'queue',l3:'delay',l4:'throughput',l5:'encapsulation',l6:'encapsulation',x1a:'topology',x1b:'access',x1c:'internet',x1d:'delay',z1:'delay',l7:'socket',l8:'services',l9:'http',l10:'http',l11:'ftp',l12:'email',l13:'dns',x2a:'httpHeader',x2b:'cache',x2c:'email',z2:'http',l14:'socket',l15:'header',l16:'checksum',l17:'tcp',l18:'arq',l19:'tcp',l20:'window',x3a:'header',x3b:'arq',x3c:'congestion',z3:'tcp',l21:'subnet',l22:'subnet',l23:'dhcp',l24:'fragment',l25:'icmp',l26:'dijkstra',l27:'dv',x4a:'subnet',x4b:'ipv6',x4c:'dv',z4:'fragment'};
export function generatedSpec(f,p){switch(f){case 'delay':return S('delay',{bits:p.bytes*8,rate:p.rate*1e6,links:p.links,km:p.km});case 'throughput':return S('throughput',{rates:p.rates.map(r=>r*1e6),file:p.fileMb*1e6});case 'http':return S('http',{objects:p.images+1,rtt:p.rtt,tx:p.tx});case 'checksum':return S('checksum',{words:[p.a,p.b],bits:16});case 'tcpAck':return S('tcp',{start:p.start,len:p.len,count:3,loss:p.gap?'data':'none',recovery:'pause-at-loss'});case 'tcpWindow':return S('window',p);case 'subnet':return S('subnet',{ip:'192.168.7.'+p.last,prefix:p.prefix,parent:p.prefix});case 'fragment':return S('fragment',{...p,header:20});case 'routing':return S('dijkstra',{edges:p.edges,start:'a',target:'d'})}}
Object.assign(originalSpecs,{'l4q0':S('throughput',{rates:[500000,2000000,1000000],file:0}),'extra-q40':S('arq',{protocol:'gbn',base:2,loss:0}),'extra-q41':S('arq',{protocol:'sr',base:2,loss:0}),'extra-q47':S('tcp',{start:0,len:100,count:1,missing:100,later:200,end:299,loss:'data'}),'v3-2-4':S('dns',{cache:'hit'}),'v3-1-1':S('bits',{value:1,bits:8})});
export function deriveSpec(q,ctx={}){if(ctx.spec)return structuredClone(ctx.spec);if(ctx.problem?.params)return generatedSpec(ctx.problem.family,ctx.problem.params);let s=ctx.transfer?transferSpecs[q.id]:originalSpecs[q.id];s=s||exerciseSpecs[q.id];if(s)return structuredClone(s);let type=topicTypes[q.lesson]||'concept',params={};if(type==='arq')params.protocol=/SR|selective/i.test(q.text)?'sr':/GBN|Go.Back/i.test(q.text)?'gbn':'stopwait';if(['l21q0','extra-q48','extra-q49'].includes(q.id))type='addressClass';if(q.id==='l5q1')type='osi';if(q.id==='l6q0'||q.id==='l26q0')type='forwarding';if(q.id==='l4q1'||q.id==='v3-1-2')type='queue';if(q.id==='extra-q57')type='ttl';if(q.id==='l0q0')type='protocol';if(q.id==='l0q1')type='star';if(q.id==='extra-q36')type='rdtNak';if(q.id==='extra-q37')type='rdtAck';if(q.id==='l9q0'||q.id==='l9q1'||q.id==='l10q0'||q.id==='extra-q23')type='httpHeader';if(q.id==='extra-q59')type='ipv6';if(q.id==='extra-q26')type='ftp';if(q.id==='l1q0'||q.id==='l1q1')type='access';if(q.id==='extra-q8'||q.id==='l2q1')type='circuit';if(q.id==='extra-q38'||q.id==='v3-3-2')params.loss='ack';if(type==='tcp')params.loss=params.loss||(/ACK|timeout/i.test(q.text)?'ack':'data');if(type==='header')params.protocol=q.lesson==='x3a'?'TCP':'UDP';if(q.id==='l25q0'||q.id==='l25q1'&&q.options?.[q.correct]?.includes('IPv6'))type='ipv6';if(q.id==='l27q0'||q.id==='extra-q63')type='internet';if(q.id==='v3-4-1')type='icmp';if(q.id==='v3-4-2')type='forwarding';if(q.id==='v3-3-1')type='header';if(q.id==='v3-2-1')type='httpHeader';if(q.id==='v3-2-4')type='dns';return {type,params,illustrative:true}}
